-- Consultant training question bank (run after add_consultant_training.sql).
--
-- This file is the source of truth for quiz questions and answers. It's
-- safe to re-run: edit a row and run the whole file again.
--   * answer is the 0-based index into options.
--   * Don't reuse or renumber IDs; attempts store them. To retire a
--     question, delete its row here and the last statement deactivates it.
--   * Each module needs at least 2 active questions.
--   * The lessons these test are in public/training-content.js.

insert into public.training_questions (id, module, prompt, options, answer, why) values
  ('q1', 'before', 'Besides this training, what do you need to finish before you can send a paid offer?',
   '["Your Stripe payout setup", "A profile photo and a short bio", "Three samples of past work on your profile", "A kickoff call with the business that posted the listing"]'::jsonb, 0,
   'The submit button stays off until your Stripe payout account is set up.'),
  ('q2', 'before', 'You sent an offer and then noticed a typo in the price. What can you do?',
   '["Edit the price from the listing page before they see it", "Send a second, corrected offer on the same listing", "Nothing, because offers can''t be changed once sent", "Ask the business to fix the price when they accept it"]'::jsonb, 2,
   'Offers can''t be edited after you send them, and you get one per listing.'),
  ('q3', 'before', 'A business accepts your offer. Where is the money right after that?',
   '["In your Stripe balance, ready to pay out to your bank", "Held in Stripe until the work is done and it''s released to you", "Still on the business''s card, charged when you deliver", "Sent to your bank account within two business days"]'::jsonb, 1,
   'The business pays when they accept, and the payment is held in Stripe until it''s released to you.'),
  ('q4', 'before', 'How does the platform fee work?',
   '["It''s a flat $10 taken from every paid offer", "It''s 10% of your whole offer, added on top of what the business pays", "It''s a percentage of the part above $10, taken from your payout", "It''s split evenly between you and the business"]'::jsonb, 2,
   'The business pays exactly your offer. The fee is 10% of the part above $10 (5% during launch), and it comes out of your payout.'),
  ('q5', 'before', 'Which pricing approach does the training recommend?',
   '["Price low on your first few jobs to build up reviews", "Charge what the work is worth, knowing your take-home first", "Start high on purpose so there''s room to come down when they counter", "Use the same hourly rate for every kind of job you take"]'::jsonb, 1,
   'Charge what the work is worth, and don''t underbid just to win the job.'),
  ('q6', 'before', 'What should a good discovery call end with?',
   '["A shared picture of the goal, and next steps you''ve both agreed on", "A full project plan and a signed agreement", "A list of the results you''ve promised the business", "A price you''ve both agreed on before you send the offer"]'::jsonb, 0,
   'End with a shared picture of the goal and next steps, then write it back to them within a day.'),
  ('q7', 'before', 'The owner says they want their website to “pop.” What should you do?',
   '["Ask what they mean and what''s prompting the change", "Send a few bold design options and let them pick one", "Make the colors brighter, since that''s usually what it means", "Mention it in your offer and sort out the details later"]'::jsonb, 0,
   'A vague goal is your cue to ask clarifying questions before you start.'),
  ('q8', 'before', 'Which of these is a promise you should make to a client?',
   '["“You''ll gain at least 1,000 new followers this month.”", "“Your sales will go up 20% by next month.”", "“I''ll post three times a week for four weeks.”", "“Your site will be on Google''s first page by spring.”"]'::jsonb, 2,
   'Promise the work you''ll deliver, not results you can''t control.'),
  ('q9', 'before', 'A business messages you about work that needs skills you don''t have, on a very tight timeline. What''s the best move?',
   '["Send an offer and learn the skills as you go", "Politely pass and leave the door open for later", "Send a low offer so they forgive any rough spots", "Leave the message unanswered and move on"]'::jsonb, 1,
   'A quick, kind no protects you, the client and your rating.'),
  ('q10', 'during', 'When should you agree with the client on how often you''ll send updates?',
   '["At kickoff, along with reply times and a contact", "In your first progress update, once work has started", "When the client asks how things are going", "When you send the offer, in the 250-character note"]'::jsonb, 0,
   'At kickoff, agree on how often you''ll update, how fast you''ll reply and who to contact.'),
  ('q11', 'during', 'Partway through, the client asks for a whole new deliverable. What should you do?',
   '["Do it for free this once, since happy clients leave better reviews", "Explain it''s outside the job and ask them to post a new listing", "Add it to the current job and ask for more money at the end", "Say yes and push your deadline back to fit it in"]'::jsonb, 1,
   'New work goes in a new listing. Explain that calmly, and don''t do it for free.'),
  ('q12', 'during', 'You''ll miss a deadline because of exams. When should you tell the client?',
   '["The same day you find out, not the day it''s due", "The day before it''s due, once you''re sure", "On the due date, along with a new date", "After exams, when you can give a clear update"]'::jsonb, 0,
   'Tell the client the day you know, not the day it''s due.'),
  ('q13', 'during', 'How should you explain your strategy to a business owner?',
   '["In plain language, focused on what they can actually do with it", "With industry terms, so they trust your expertise", "In a detailed written report they can read later", "Briefly, since owners usually just want the result"]'::jsonb, 0,
   'Most owners aren''t marketers, so skip the jargon and focus on what they can do with it.'),
  ('q14', 'during', 'Halfway through, you''re unsure what the client meant in a message. What should you do?',
   '["Ask them to clarify in the engagement''s message thread", "Make your best guess so you don''t bother them", "Do both versions and let them pick one when you deliver", "Wait for your next update and ask then"]'::jsonb, 0,
   'Clarifying questions don''t stop after kickoff, and asking isn''t bothering them.'),
  ('q15', 'during', 'Which use of AI is not okay?',
   '["Brainstorming headline ideas, then editing them yourself", "Writing a first draft with AI, then fact-checking every claim", "Putting their customer list in an AI tool without asking", "Using AI to summarize public research on their industry"]'::jsonb, 2,
   'Never put a client''s private data into an AI tool without their OK.'),
  ('q16', 'after', 'The client says, “Looks good, let me think about it.” What should you do?',
   '["Mark it delivered now so the 14 days start", "Get their feedback, revise, then mark it delivered", "Wait a day, then mark it delivered if they''re quiet", "Mark it delivered and offer free changes afterward"]'::jsonb, 1,
   'Feedback isn''t the same as done. Mark the work delivered once they have everything they need.'),
  ('q17', 'after', 'After you mark the work delivered, what happens if the business does nothing?',
   '["It''s released to you automatically once the 14 days are up", "The payment goes back to the business after 14 days", "The payment stays held until they respond", "Grassroots reviews it after 14 days before paying you"]'::jsonb, 0,
   'If they take no action in 14 days, the payment releases to you automatically.'),
  ('q18', 'after', 'The business requests changes after you mark the work delivered. What happens next?',
   '["You update the work and mark it delivered again", "The payment is released, and changes are a new job", "The 14 days keep counting while you make the changes", "Grassroots steps in to decide if the changes are fair"]'::jsonb, 0,
   'Requesting changes clears the delivered mark, and the 14 days restart when you deliver again.'),
  ('q19', 'after', 'A business reports a problem, and Grassroots finds the work falls short but can be fixed. What are your options?',
   '["Redo it once within 5 days, or give the money back", "Redo it as many times as the business asks you to", "Keep half the payment, and the business gets the other half back", "Fix it any time in the next 14 days to get paid"]'::jsonb, 0,
   'You get one redo within 5 days. If you don''t answer, it counts as giving the money back.'),
  ('q20', 'after', 'Which statement about reviews is true?',
   '["Reviews are final, and your rating moves you up the stage ladder", "You can ask the business to edit their review within 7 days of posting", "Grassroots removes negative reviews if you ask", "Reviews are optional and don''t affect your stage"]'::jsonb, 0,
   'Reviews can''t be edited, and your rating helps move you up the stage ladder.'),
  ('q21', 'after', 'Which statement about taxes is true?',
   '["Grassroots holds back income tax from each payout", "You only owe tax if you receive a 1099 form", "You owe tax on what you earn, form or no form", "You upload a new W-9 before every engagement"]'::jsonb, 2,
   'You owe income and self-employment tax on what you earn, whether or not you get a form. This isn''t tax advice.'),
  ('q22', 'trust', 'A client you met on Grassroots offers to pay you directly next month to skip the fees. What should you do?',
   '["Accept, since it''s a new project and not the one you met through", "Accept, as long as you''ve finished the first engagement", "Decline, because paid work with them stays here for 12 months", "Accept, and send Grassroots its fee yourself"]'::jsonb, 2,
   'For 12 months, moving paid work with them off Grassroots breaks the Terms and can close your account.'),
  ('q23', 'trust', 'The engagement has ended. What should you do with the client''s logins and customer data?',
   '["Return or delete them, and keep anything you saw private", "Keep them in case they hire you again", "Keep the logins but delete the customer data", "Save a copy for your portfolio, then delete the rest"]'::jsonb, 0,
   'Use client data only for the engagement, then return or delete it.'),
  ('q24', 'trust', 'How should you describe yourself to a client?',
   '["Honestly, as a student, without making your experience sound bigger", "As a freelancer, so they take you more seriously", "By your skills only, without mentioning school", "As part of a team, even if you work alone"]'::jsonb, 0,
   'Be upfront that you''re a student, and don''t oversell your experience.'),
  ('q25', 'trust', 'A client has gone quiet for two weeks in the middle of an engagement. What''s the best step?',
   '["Follow up in messages, then contact support early", "Mark the work delivered so the 14 days start", "Keep working and wait for them to come back", "Text or email them outside Grassroots to reach them"]'::jsonb, 0,
   'Follow up on the platform, and contact support early if they stay quiet.'),
  ('q26', 'before', 'What should you wear for a video call with a new client?',
   '["Business casual, like a collared shirt or sweater", "Whatever''s comfortable, since it''s only video", "A clean hoodie, since most clients are casual", "A full suit and tie, no matter who the client is"]'::jsonb, 0,
   'Dress business casual for every client call, including video, and keep your camera on.'),
  ('q27', 'during', 'A client asks a question you can''t fully answer yet. What should you do?',
   '["Reply within a day and say when you''ll have an answer", "Wait until you have the complete answer so you only reply once", "Answer it in your next scheduled update", "Reply with your best guess so they''re not waiting"]'::jsonb, 0,
   'Reply within one business day, even if it''s only to say when you''ll have the full answer.'),
  ('q28', 'during', 'You''ll be hard to reach for a week during finals. What''s the best move?',
   '["Tell the client ahead of time, with the dates you''ll be away", "Reply when you can and catch up after finals", "Answer only urgent messages until finals are over", "Push your deadline back a week and tell them after finals are over"]'::jsonb, 0,
   'Never go silent. Tell the client before you''re unavailable, with the dates and when they''ll hear from you.')
on conflict (id) do update set
  module = excluded.module,
  prompt = excluded.prompt,
  options = excluded.options,
  answer = excluded.answer,
  why = excluded.why,
  active = true;

-- Retire anything no longer listed above.
update public.training_questions
set active = false
where id not in (
  'q1','q2','q3','q4','q5','q6','q7','q8','q9','q10','q11','q12','q13','q14',
  'q15','q16','q17','q18','q19','q20','q21','q22','q23','q24','q25','q26','q27','q28'
);
